		if (value != null) {
			startObject(name);
			value.appendTo(this);
			endObject();
		} else {
			attribute(name, (Object) null);
		}
		return this;
	}

	public ToStringTreeBuilder value(Object value) {
		return attribute(null, value);
	}

	public ToStringTreeBuilder startObject() {
		return startObject(null);
	}

	public ToStringTreeBuilder startObject(String name) {
		beforeElement();
		builder.append(style.startObject);
		++depth;
		first = true;
		appendNewline();
		return this;
	}

	public ToStringTreeBuilder endObject() {
		if (depth == 0) {
			throw new AssertionFailure("Cannot pop, already at root");
		}
		--depth;
		if (!first) {
			appendNewline();
		}
		first = false;
		appendIndent();
		builder.append(style.endObject);
		return this;
	}

	public ToStringTreeBuilder startList() {
		return startList(null);
	}

	public ToStringTreeBuilder startList(String name) {
		beforeElement();
		builder.append(style.startList);
		++depth;
		first = true;
		appendNewline();
		return this;
	}

	public ToStringTreeBuilder endList() {
		if (depth == 0) {
			throw new AssertionFailure("Cannot pop, already at root");
		}
		--depth;
		if (!first) {
			appendNewline();
		}
		first = false;
		appendIndent();
		builder.append(style.endList);
		return this;
	}

	private void beforeElement() {
		if (first) {
			first = false;
			appendIndent();
		} else {
			builder.append(style.entrySeparator);
			appendNewline();
			appendIndent();
		}
	}

	private void appendNewline() {
		builder.append(style.newline);
	}

	private void appendIndent() {
		if (!style.indent.isEmpty()) {
