	private enum DocumentWorkCallKind {
		CREATE,
		DISCARD,
		EXECUTE,
		CREATE_AND_DISCARD,
		CREATE_AND_EXECUTE,
		CREATE_AND_EXECUTE_OUT_OF_ORDER;
