					float dist = ls.distanceTo(previousAction);
					actionDist += dist;
					if(actionDist >= DISTANCE_ACTION) {
						actionPoints.add(calculateProjection(1 - (actionDist - DISTANCE_ACTION) / dist, previousAction, ls));
						actionPoints.add(null);
						prevFinishPoint = i;
						previousAction = null;
						actionDist = 0;
					} else {
