		}
		else if ( major == 5 ) {
			if ( !minorOptional.isPresent() ) {
				throw log.ambiguousElasticsearchVersion( version );
			}
			int minor = minorOptional.getAsInt();
			if ( minor < 6 ) {
				throw log.unsupportedElasticsearchVersion( version );
			}
			return new Elasticsearch56ModelDialect();
