    private void doMassIndexingWithFailure(MassIndexer massIndexer,
            ThreadExpectation threadExpectation,
            Consumer<Throwable> thrownExpectation,
            Runnable... expectationSetters) {
        doMassIndexingWithFailure(
                massIndexer,
                threadExpectation,
