					session.get( Person.class, JANE_SMITH_ID ),
					session.get( Person.class, JANE_FONDA_ID ),
					session.get( Person.class, JANE_PORTER_ID )
			);

			results = dao.listTopShortTermBorrowers( 0, 3 );
			assertThat( results ).containsExactly(
