	private void initData() {
		IndexIndexingPlan<? extends DocumentElement> plan = indexManager.createIndexingPlan();
		addDocumentToPlan(plan, FIRST_ID, "text 1", 37, 37, 37, "a", "z", "z");
		addDocumentToPlan(plan, SECOND_ID, null, 78, 78, 78, "z", "a", "z");
		addDocumentToPlan(plan, THIRD_ID, null, 13, 13, 13, "z", "z", "a");
		addDocumentToPlan(plan, FOURTH_ID, null, 89, 89, 89, "z", "z", "z");
		addDocumentToPlan(plan, FIFTH_ID, "text 2", 1, null, null, "zz", "zz", "zz");

		plan.execute().join();

		// Check that all documents are searchable
		StubMappingScope scope = indexManager.createScope();
		SearchQuery<DocumentReference> query = scope.query()
				.predicate( f -> f.matchAll() )
				.toQuery();
		assertThat( query ).hasDocRefHitsAnyOrder(
