								+ "'ignore_malformed': true" // Ignored during validation
						+ "},"
						+ "'NOTmyField': {" // Ignored during validation
								+ "'type': 'date',"
								+ "'index': true"
						+ "}"
				)
		);

		setupAndValidate( index );

		// If we get here, it means validation passed (no exception was thrown)
	}

