methodSignature: org.hibernate.search.engine.common.impl.IndexManagerBuildingStateHolder.BackendInitialBuildState#getIndexManagerBuildingState
 methodBody: IndexManagerInitialBuildState<?> getIndexManagerBuildingState(
				String indexName, boolean multiTenancyEnabled) {
IndexManagerInitialBuildState<?> state=indexManagerBuildStateByName.get(indexName);
if(state == null){ConfigurationPropertySource indexPropertySource=EngineConfigurationUtils.getIndex(backendPropertySource,defaultIndexPropertySource,indexName);
IndexManagerBuilder<D> builder=backend.createIndexManagerBuilder(indexName,multiTenancyEnabled,backendBuildContext,indexPropertySource);
IndexSchemaRootNodeBuilder schemaRootNodeBuilder=builder.getSchemaRootNodeBuilder();
IndexedEntityBindingContext bindingContext=new IndexedEntityBindingContextImpl(schemaRootNodeBuilder);
state=new IndexManagerInitialBuildState<>(backendName,indexName,builder,bindingContext);
indexManagerBuildStateByName.put(indexName,state);
}return state;
}

methodSignature: org.hibernate.search.engine.common.impl.IndexManagerBuildingStateHolder#getBackend
 methodBody: BackendInitialBuildState<?> getBackend(String backendName) {
if(StringHelper.isEmpty(backendName)){backendName=getDefaultBackendName();
}BackendInitialBuildState<?> backendBuildState=backendBuildStateByName.get(backendName);
if(backendBuildState == null){throw new AssertionFailure("Mapper asking for a reference to backend '" + backendName + "', which was not declared in advance." + " There is a bug in Hibernate Search, please report it.");
